  window.DragonboundPersonalityDebug={inspect(){if(currentAccountSlug()!=='admin')return null;const a=engine.actor;if(!a)return null;return{name:a.dragon.name,archetype:a.dragon.personality?.archetype,coreStats:{...a.coreStats},quirks:[...a.assignedTraits],discovered:[...a.discoveredTraits],needs:{...a.needs},preferences:typeof structuredClone==='function'?structuredClone(a.preferences):JSON.parse(JSON.stringify(a.preferences)),memory:a.behaviourSnapshot(),scores:{...a.lastScores}};},simulate(minutes=60){if(currentAccountSlug()!=='admin')return null;return engine.actor?.simulateBehaviour(minutes)||null;},save(){if(currentAccountSlug()==='admin')engine.saveBehaviour(true);}};
